    "cap.step1_desc": "PDF, స్కాన్ చేసిన పత్రాలు, Word ఫైల్‌లు లేదా సాదా వచనాన్ని అప్‌లోడ్ చేయండి. సిస్టమ్ స్వయంచాలకంగా పత్రాలను వ్యక్తిగత నిబంధనలుగా విభజిస్తుంది.",
