    "cap.lead": "சட்டப்படியான குருட்டுப் புள்ளிகளை அகற்றவும், பேச்சுவார்த்தை சுழற்சிகளை விரைவுபடுத்தவும், துல்லியமான ஒப்பந்த நுண்ணறிவுடன் நிறுவன நலன்களைப் பாதுகாக்கவும்.",
    "cap.step1_num": "01 / பிரித்தெடுத்தல் மற்றும் பாகுபடுத்தல்",
    "cap.step1_title": "பல வடிவ ஆவண ஏற்பு",
    "cap.step1_desc": "PDF, ஸ்கேன் செய்யப்பட்ட ஆவணங்கள், Word கோப்புகள் அல்லது எளிய உரையைப் பதிவேற்றவும். அமைப்பு சிக்கலான ஆவணங்களை பகுப்பாய்வு செய்யக்கூடிய விதிகளாகப் பிரிக்கிறது.",
