    "cap.step2_desc": "மறைக்கப்பட்ட பொறுப்புகள், ஒருதலைப்பட்ச இழப்பீடுகள், வரம்பற்ற சேதங்கள் மற்றும் முறையற்ற முடித்தல் விதிகளை உடனடியாகக் கண்டறிகிறது.",
    "cap.step3_num": "03 / ஸ்மார்ட் ரெட்லைனிங்",
