    "cap.step3_desc": "உங்கள் நிலையைப் பாதுகாக்க சமநிலையான மாற்று சொற்களை உருவாக்குகிறது, ஒரே கிளிக்கில் நகல் மற்றும் வேறுபாடுகளுடன்.",
    "cap.step4_num": "04 / இணக்கம் & ஏற்றுமதி",
