    "cap.step4_desc": "உங்கள் நிறுவன விதிமுறைகளுக்கு எதிராக ஒப்பந்தங்களைச் சரிபார்க்கிறது, PDF சுருக்கங்களை ஏற்றுமதி செய்கிறது மற்றும் தணிக்கை பதிவுகளைப் பராமரிக்கிறது.",
    "cap.detail1_tag": "FEATURE 01 • DOCUMENT ENGINE",
    "cap.detail1_title": "தனித்தனி விதி பிரிப்பு",
    "cap.detail1_desc": "ClauseGuard breaks down monolithic legal contracts into atomic, numbered clauses. Scanned agreements undergo image enhancement and OCR preprocessing before parsing.",
    "cap.detail2_tag": "FEATURE 02 • RISK SCORING",
    "cap.detail2_title": "துல்லியமான ஆபத்து வகைப்பாடு",
    "cap.detail2_desc": "Deterministic scoring ensures consistent, auditable risk evaluations across 15+ specialized commercial categories without the hallucinations common in generic chatbots.",
    "cap.detail3_tag": "FEATURE 03 • NEGOTIATION COPILOT",
    "cap.detail3_title": "எளிய தமிழ் சுருக்கங்கள் & திருத்தங்கள்",
    "cap.detail3_desc": "When a risk is detected, ClauseGuard translates dense legalese into plain executive summaries and crafts ready-to-negotiate counter-proposals.",
    "cap.detail4_tag": "FEATURE 04 • ENTERPRISE AUDIT",
    "cap.detail4_title": "நிறுவன கொள்கை இணக்கம்",
    "cap.detail4_desc": "Ensure every sales or procurement agreement strictly matches your company's approved legal standards. Automatically flag non-standard terms before signing.",
