    "cap.heading": "क्लॉजगार्ड आपके व्यवसाय की सुरक्षा कैसे करता है।",
    "cap.lead": "कानूनी कमियों को समाप्त करें, बातचीत चक्रों में तेजी लाएं और सटीक अनुबंध विश्लेषण से कॉर्पोरेट हितों की रक्षा करें।",
    "cap.step1_num": "01 / निष्कर्षण और पार्सिंग",
    "cap.step1_title": "मल्टी-फॉर्मेट दस्तावेज़ इनपुट",
    "cap.step1_desc": "PDF, स्कैन किए गए दस्तावेज़, Word फ़ाइलें या सादा पाठ अपलोड करें। सिस्टम स्वचालित रूप से जटिल अनुबंधों को अलग-अलग शर्तों में विभाजित करता है।",
    "cap.step2_num": "02 / जोखिम पहचान",
    "cap.step2_title": "स्वचालित गंभीरता स्कोरिंग",
    "cap.step2_desc": "छिपी देनदारियों, एकतरफा क्षतिपूर्ति, असीमित नुकसान और अनुचित समाप्ति शर्तों को तुरंत चिह्नित करता है।",
    "cap.step3_num": "03 / स्मार्ट रेडलाइनिंग",
    "cap.step3_title": "स्वायत्त जवाबी प्रस्ताव",
    "cap.step3_desc": "आपके पक्ष की सुरक्षा के लिए संतुलित प्रतिस्थापन शब्दावली तैयार करता है, एक-क्लिक कॉपी और रेडलाइन अंतर के साथ।",
    "cap.step4_num": "04 / अनुपालन और निर्यात",
    "cap.step4_title": "कॉर्पोरेट प्लेबुक ऑडिट",
    "cap.step4_desc": "आपके संगठनात्मक मानकों के खिलाफ समझौतों को मान्य करता है, कार्यकारी PDF सारांश निर्यात करता है और ऑडिट ट्रेल्स रिकॉर्ड करता है।",
    "cap.detail1_tag": "FEATURE 01 • DOCUMENT ENGINE",
    "cap.detail1_title": "परमाणु खंड विभाजन",
    "cap.detail1_desc": "ClauseGuard breaks down monolithic legal contracts into atomic, numbered clauses. Scanned agreements undergo image enhancement and OCR preprocessing before parsing.",
    "cap.detail2_tag": "FEATURE 02 • RISK SCORING",
    "cap.detail2_title": "सटीक जोखिम वर्गीकरण",
    "cap.detail2_desc": "Deterministic scoring ensures consistent, auditable risk evaluations across 15+ specialized commercial categories without the hallucinations common in generic chatbots.",
    "cap.detail3_tag": "FEATURE 03 • NEGOTIATION COPILOT",
    "cap.detail3_title": "सरल भाषा सारांश और रेडलाइन",
    "cap.detail3_desc": "When a risk is detected, ClauseGuard translates dense legalese into plain executive summaries and crafts ready-to-negotiate counter-proposals.",
    "cap.detail4_tag": "FEATURE 04 • ENTERPRISE AUDIT",
    "cap.detail4_title": "कॉर्पोरेट प्लेबुक अनुपालन",
    "cap.detail4_desc": "Ensure every sales or procurement agreement strictly matches your company's approved legal standards. Automatically flag non-standard terms before signing.",
    "wf.eyebrow": "एंटरप्राइज कार्यप्रवाह",
