    "wf.n1_desc": "Accepts PDF, DOCX, scanned images, and raw text with instant OCR text extraction.",
    "wf.n2_num": "02 / SEGMENT",
    "wf.n2_title": "खंड सीमा मानचित्रण",
    "wf.n2_desc": "Isolates individual legal clauses, section headings, and cross-references automatically.",
