    "wf.n6_title": "एक-क्लिक रेडलाइनिंग",
    "wf.n6_desc": "Suggests legally sound counter-clauses with clear rationale ready for negotiation.",
    "wf.n7_num": "07 / AUDIT",
    "wf.n7_title": "प्लेबुक सत्यापन",
    "wf.n7_desc": "Validates contract terms against your internal corporate risk tolerance guidelines.",
    "wf.n8_num": "08 / EXPORT",
    "wf.n8_title": "कार्यकारी रिपोर्ट",
    "wf.n8_desc": "Produces enterprise PDF risk summaries and stores encrypted audit trails.",
    "wf.sec_badge": "🛡️ शून्य डेटा प्रतिधारण गारंटी",
    "wf.sec_title": "गोपनीय समझौतों के लिए बैंक-स्तरीय सुरक्षा",
    "wf.sec_desc": "आपके अनुबंध संवेदनशील वाणिज्यिक नियम और मूल्य निर्धारण रखते हैं। क्लॉजगार्ड सख्त गोपनीयता गारंटी के साथ बनाया गया है।",
