    "wf.lead": "आधुनिक कॉर्पोरेट सौदों में आसानी से एकीकृत होने के लिए डिज़ाइन किया गया।",
    "wf.n1_num": "01 / INGEST",
    "wf.n1_title": "सार्वभौमिक फ़ाइल इनपुट",
    "wf.n1_desc": "Accepts PDF, DOCX, scanned images, and raw text with instant OCR text extraction.",
