    "wf.sec_title": "गोपनीय समझौतों के लिए बैंक-स्तरीय सुरक्षा",
    "wf.sec_desc": "आपके अनुबंध संवेदनशील वाणिज्यिक नियम और मूल्य निर्धारण रखते हैं। क्लॉजगार्ड सख्त गोपनीयता गारंटी के साथ बनाया गया है।",
