    "cap.step3_desc": "আপনার সুরক্ষার জন্য সুষম বিকল্প শর্তাবলী তৈরি করে, একক ক্লিকে অনুলিপি সহ।",
    "cap.step4_num": "04 / সম্মতি ও রপ্তানি",
