    "wf.n4_desc": "Generates color-coded severity heatmaps highlighting high-risk liability exposure.",
    "wf.n5_num": "05 / EXPLAIN",
    "wf.n5_title": "सरल भाषा सारांश",
    "wf.n5_desc": "Translates dense legalese into concise business summaries for commercial teams.",
