    "Contracts, dissected with precision.": "ஒப்பந்தங்கள், துல்லியமாக பிரிக்கப்படுகின்றன.",
    "AI-Powered Legal Intelligence": "AI-இயங்கும் சட்ட நுண்ணறிவு",
    "Autonomous legal intelligence designed for enterprises, law firms, and procurement teams. Extract dense obligations, flag predatory indemnities, and redline contracts in seconds without hallucination.": "நிறுவனங்கள், சட்ட நிறுவனங்கள் மற்றும் கொள்முதல் குழுக்களுக்கான தன்னாட்சி சட்ட நுண்ணறிவு. கடமைகளைப் பிரித்தெடுக்கவும், ஆபத்தான இழப்பீடுகளைக் கண்டறியவும், வினாடிகளில் ஒப்பந்தங்களை மறுவடிவமைக்கவும்.",
    "Launch ClauseGuard Studio": "க்ளாஸ்கார்ட் ஸ்டுடியோவைத் தொடங்குக",
    "Test Risk Playground": "ஆபத்து களத்தை சோதிக்கவும்",
    "Model Precision": "மாதிரி துல்லியம்",
