    "Amber Warnings": "எச்சரிக்கைகள்",
    "Safe Clauses": "பாதுகாப்பான பிரிவுகள்",
    "Platform Capabilities": "தளத்தின் திறன்கள்",
    "How ClauseGuard protects your business.": "க்ளாஸ்கார்ட் உங்கள் வணிகத்தை எவ்வாறு பாதுகாக்கிறது.",
    "Eliminate legal blind spots, accelerate negotiation cycles, and protect corporate interests with calibrated contract intelligence.": "சட்டப்படியான குருட்டுப் புள்ளிகளை அகற்றவும், பேச்சுவார்த்தை சுழற்சிகளை விரைவுபடுத்தவும், துல்லியமான ஒப்பந்த நுண்ணறிவுடன் நிறுவன நலன்களைப் பாதுகாக்கவும்.",
    "01 / EXTRACTION & PARSING": "01 / பிரித்தெடுத்தல் மற்றும் பாகுபடுத்தல்",
    "Multi-Format Ingestion": "பல வடிவ ஆவண ஏற்பு",
    "Upload PDF, scanned documents, Word files, or plain text. The system automatically segments complex documents into discrete, analyzable terms.": "PDF, ஸ்கேன் செய்யப்பட்ட ஆவணங்கள், Word கோப்புகள் அல்லது எளிய உரையைப் பதிவேற்றவும். அமைப்பு சிக்கலான ஆவணங்களை பகுப்பாய்வு செய்யக்கூடிய விதிகளாகப் பிரிக்கிறது.",
    "02 / RISK DETECTION": "02 / ஆபத்து கண்டறிதல்",
    "Automated Severity Scoring": "தானியங்கி தீவிரம் மதிப்பீடு",
    "Instantly flags hidden liabilities, predatory indemnities, unlimited damages, and overreaching termination covenants.": "மறைக்கப்பட்ட பொறுப்புகள், ஒருதலைப்பட்ச இழப்பீடுகள், வரம்பற்ற சேதங்கள் மற்றும் முறையற்ற முடித்தல் விதிகளை உடனடியாகக் கண்டறிகிறது.",
    "03 / SMART REDLINING": "03 / ஸ்மார்ட் ரெட்லைனிங்",
    "Autonomous Counter-Proposals": "தன்னாட்சி எதிர் முன்மொழிவுகள்",
    "Generates balanced replacement wording tailored to protect your position, with one-click copy and redline diffs.": "உங்கள் நிலையைப் பாதுகாக்க சமநிலையான மாற்று சொற்களை உருவாக்குகிறது, ஒரே கிளிக்கில் நகல் மற்றும் வேறுபாடுகளுடன்.",
    "04 / COMPLIANCE & EXPORT": "04 / இணக்கம் & ஏற்றுமதி",
    "Corporate Playbook Audit": "நிறுவன விதிமுறை தணிக்கை",
    "Validates agreements against your custom organizational standards, exports executive PDF summaries, and logs team audit trails.": "உங்கள் நிறுவன விதிமுறைகளுக்கு எதிராக ஒப்பந்தங்களைச் சரிபார்க்கிறது, PDF சுருக்கங்களை ஏற்றுமதி செய்கிறது மற்றும் தணிக்கை பதிவுகளைப் பராமரிக்கிறது.",
    "Enterprise Workflow": "நிறுவன பணிப்பாய்வு",
    "Built for end-to-end contract governance.": "முழுமையான ஒப்பந்த நிர்வாகத்திற்காக உருவாக்கப்பட்டது.",
    "Interactive Sandbox": "ஊடாடும் சோதனை அரங்கம்",
    "Test a clause right now.": "இப்போதே ஒரு விதியைச் சோதிக்கவும்.",
    "Choose a preset legal clause or paste your own contract excerpt below. Experience instant real-time risk assessment powered by the ClauseGuard model.": "முன்அமைக்கப்பட்ட சட்ட விதியைத் தேர்வுசெய்யவும் அல்லது உங்கள் ஒப்பந்த உரையை கீழே ஒட்டவும். நிகழ்நேர ஆபத்து மதிப்பீட்டைப் பெறுங்கள்.",
