    "dissected with precision.": "துல்லியமாக பிரிக்கப்படுகின்றன.",
    "Risk Score": "ஆபத்து மதிப்பெண்",
    "FEATURE 01 • DOCUMENT ENGINE": "FEATURE 01 • DOCUMENT ENGINE",
    "ClauseGuard breaks down monolithic legal contracts into atomic, numbered clauses. Scanned agreements undergo image enhancement and OCR preprocessing before parsing.": "ClauseGuard breaks down monolithic legal contracts into atomic, numbered clauses. Scanned agreements undergo image enhancement and OCR preprocessing before parsing.",
    "FEATURE 02 • RISK SCORING": "FEATURE 02 • RISK SCORING",
    "Deterministic scoring ensures consistent, auditable risk evaluations across 15+ specialized commercial categories without the hallucinations common in generic chatbots.": "Deterministic scoring ensures consistent, auditable risk evaluations across 15+ specialized commercial categories without the hallucinations common in generic chatbots.",
    "FEATURE 03 • NEGOTIATION COPILOT": "FEATURE 03 • NEGOTIATION COPILOT",
    "When a risk is detected, ClauseGuard translates dense legalese into plain executive summaries and crafts ready-to-negotiate counter-proposals.": "When a risk is detected, ClauseGuard translates dense legalese into plain executive summaries and crafts ready-to-negotiate counter-proposals.",
    "FEATURE 04 • ENTERPRISE AUDIT": "FEATURE 04 • ENTERPRISE AUDIT",
    "Ensure every sales or procurement agreement strictly matches your company's approved legal standards. Automatically flag non-standard terms before signing.": "Ensure every sales or procurement agreement strictly matches your company's approved legal standards. Automatically flag non-standard terms before signing.",
    "Designed to fit seamlessly into modern corporate deal cycles, from initial draft ingestion to final executive sign-off.": "தொடக்க வரைவு முதல் இறுதி ஒப்புதல் வரை அனைத்து நிலைகளிலும் தடையின்றி செயல்பட வடிவமைக்கப்பட்டுள்ளது.",
    "01 / INGEST": "01 / INGEST",
    "Accepts PDF, DOCX, scanned images, and raw text with instant OCR text extraction.": "Accepts PDF, DOCX, scanned images, and raw text with instant OCR text extraction.",
    "02 / SEGMENT": "02 / SEGMENT",
    "Isolates individual legal clauses, section headings, and cross-references automatically.": "Isolates individual legal clauses, section headings, and cross-references automatically.",
    "03 / CLASSIFY": "03 / CLASSIFY",
    "Categorizes clauses into 15+ areas including Indemnity, Liability, IP, and Termination.": "Categorizes clauses into 15+ areas including Indemnity, Liability, IP, and Termination.",
    "04 / SCORE": "04 / SCORE",
    "Generates color-coded severity heatmaps highlighting high-risk liability exposure.": "Generates color-coded severity heatmaps highlighting high-risk liability exposure.",
    "05 / EXPLAIN": "05 / EXPLAIN",
    "Translates dense legalese into concise business summaries for commercial teams.": "Translates dense legalese into concise business summaries for commercial teams.",
    "06 / MITIGATE": "06 / MITIGATE",
    "Suggests legally sound counter-clauses with clear rationale ready for negotiation.": "Suggests legally sound counter-clauses with clear rationale ready for negotiation.",
    "07 / AUDIT": "07 / AUDIT",
    "Validates contract terms against your internal corporate risk tolerance guidelines.": "Validates contract terms against your internal corporate risk tolerance guidelines.",
    "08 / EXPORT": "08 / EXPORT",
    "Produces enterprise PDF risk summaries and stores encrypted audit trails.": "Produces enterprise PDF risk summaries and stores encrypted audit trails.",
    "🛡️ ZERO DATA RETENTION GUARANTEE": "🛡️ பூஜ்ஜிய தரவு சேமிப்பு உத்தரவாதம்",
    "Your agreements contain sensitive commercial terms, pricing structures, and proprietary data. ClauseGuard is engineered from the ground up with strict confidentiality guarantees.": "உங்கள் ஆவணங்கள் முக்கிய வணிக நிபந்தனைகளைக் கொண்டுள்ளன. க்ளாஸ்கார்ட் கடுமையான ரகசியத்தன்மை உத்தரவாதங்களுடன் உருவாக்கப்பட்டுள்ளது.",
    "No Model Training: Your documents are never used to train or fine-tune AI models.": "No Model Training: Your documents are never used to train or fine-tune AI models.",
    "In-Memory Processing: Contract contents are analyzed in encrypted volatile memory.": "In-Memory Processing: Contract contents are analyzed in encrypted volatile memory.",
    "End-to-End Encryption: 256-bit AES encryption at rest and TLS 1.3 in transit.": "End-to-End Encryption: 256-bit AES encryption at rest and TLS 1.3 in transit.",
    "Role-Based Access: Multi-user workspace controls with granular team permissions.": "Role-Based Access: Multi-user workspace controls with granular team permissions.",
    "Paste any contract clause or text here to dissect risk...": "ஆபத்தை பகுப்பாய்வு செய்ய எந்த ஒப்பந்த விதியையும் இங்கே ஒட்டவும்…",
    "Risk Confidence": "ஆபத்து நம்பிக்கை",
    "Upload any contract and get full clause classification, risk heatmaps, and plain-English summaries in under 30 seconds.": "எந்தவொரு ஒப்பந்தத்தையும் பதிவேற்றி 30 வினாடிகளில் முழுமையான விதி வகைப்பாடு மற்றும் எளிய சுருக்கங்களைப் பெறுங்கள்.",
    "Access your contract audits, workspaces, and team playbooks.": "உங்கள் ஒப்பந்த தணிக்கைகள் மற்றும் பணியிடங்களை அணுகவும்.",
    "Join high-velocity teams automating their contract review cycles.": "ஒப்பந்த மதிப்பாய்வு சுழற்சிகளை தானியங்குபடுத்தும் குழுக்களுடன் இணையுங்கள்.",
