    "Upload any contract or legal document. Our AI extracts every clause, flags high-risk language, and generates an actionable risk report — in seconds.": "எந்தவொரு ஒப்பந்தம் அல்லது சட்ட ஆவணத்தையும் பதிவேற்றவும். எங்கள் AI ஒவ்வொரு விதியையும் பிரித்தெடுத்து, ஆபத்தான பகுதிகளைக் கண்டறிந்து வினாடிகளில் அறிக்கை அளிக்கிறது.",
