    "Drop files or click to upload — PDF, DOCX, DOC, Images, TXT, RTF — max 16 MB each": "ఫైళ్ళను వదలండి లేదా అప్‌లోడ్ చేయడానికి క్లిక్ చేయండి — PDF, DOCX, DOC, చిత్రాలు, TXT — గరిష్టంగా 16 MB",
